head.b:skin:
/* =========================================================
   Trend Kaigai Clean Template v1
   Public-site-inspired clean Blogger template
   ========================================================= */
:root{
  --bg:#f6f7f9;
  --surface:#ffffff;
  --text:#17191d;
  --muted:#6b7280;
  --line:#e5e7eb;
  --accent:#1677d2;
  --accent-dark:#0d5da9;
  --nav:#111318;
  --max:1180px;
  --sidebar:320px;
  --radius:3px;
  --shadow:0 1px 4px rgba(0,0,0,.08);
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  margin:0;
  background:var(--bg);
  color:var(--text);
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans JP","Hiragino Kaku Gothic ProN","Yu Gothic",Meiryo,sans-serif;
  font-size:16px;
  line-height:1.85;
  overflow-wrap:anywhere;
}
a{color:inherit;text-decoration:none}
a:hover{color:var(--accent)}
img{max-width:100%;height:auto}
button,input{font:inherit}

.site-header{background:var(--surface);border-bottom:1px solid var(--line)}
.header-inner{max-width:var(--max);margin:0 auto;padding:28px 20px 24px}
.site-title{margin:0;font-size:30px;line-height:1.35;font-weight:800;letter-spacing:.01em}
.site-title a:hover{color:inherit}
.site-description{margin:10px 0 0;color:var(--muted);font-size:14px;line-height:1.7;max-width:850px}

.primary-nav{background:var(--nav);color:#fff}
.nav-inner{max-width:var(--max);margin:0 auto;padding:0 20px;display:flex;align-items:center;min-height:48px}
.nav-home{display:inline-flex;align-items:center;padding:13px 17px;font-size:14px;font-weight:700;background:rgba(255,255,255,.06)}
.nav-home:hover{color:#fff;background:rgba(255,255,255,.12)}
.menu-slot{flex:1;min-width:0}
.menu-slot .widget{margin:0}
.menu-slot .widget-title{display:none}
.menu-slot ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap}
.menu-slot li{margin:0}
.menu-slot a{display:block;color:#fff;padding:13px 15px;font-size:14px;font-weight:600}
.menu-slot a:hover{background:rgba(255,255,255,.1);color:#fff}

.page-shell{max-width:var(--max);margin:28px auto 52px;padding:0 20px;display:grid;grid-template-columns:minmax(0,1fr) var(--sidebar);gap:30px;align-items:start}
.content-column{min-width:0}
.sidebar-column{min-width:0}

.status-msg-wrap,.blog-feeds,.post-feeds{display:none}
.date-header{display:none}

.post-outer-container,.post-outer{margin:0 0 24px}
.post-card,.single-post{
  background:var(--surface);
  border:1px solid var(--line);
  border-radius:var(--radius);
  box-shadow:var(--shadow);
}
.post-card{overflow:hidden}
.post-card-grid{display:grid;grid-template-columns:minmax(230px,38%) minmax(0,1fr)}
.post-card-media{display:block;background:#e9edf2;min-height:235px;overflow:hidden}
.post-card-media img{width:100%;height:100%;min-height:235px;object-fit:cover;display:block;transition:transform .25s ease}
.post-card-media:hover img{transform:scale(1.02)}
.post-card-placeholder{width:100%;height:100%;min-height:235px;display:grid;place-items:center;color:#9ca3af;font-size:13px;background:linear-gradient(135deg,#eef1f5,#e1e6ec)}
.post-card-content{padding:24px 25px 22px}
.post-labels{display:flex;gap:7px;flex-wrap:wrap;margin:0 0 10px}
.post-labels a{display:inline-block;background:var(--accent);color:#fff;padding:3px 9px;border-radius:2px;font-size:11px;font-weight:700;line-height:1.5}
.post-labels a:hover{background:var(--accent-dark);color:#fff}
.post-card-title{margin:0 0 10px;font-size:22px;line-height:1.55;font-weight:800}
.post-card-title a:hover{color:var(--accent)}
.post-meta{color:var(--muted);font-size:12px;margin-bottom:10px}
.post-snippet{margin:0;color:#4b5563;font-size:14px;line-height:1.85;display:-webkit-box;-webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden}
.read-more{display:inline-block;margin-top:15px;color:var(--accent);font-weight:700;font-size:13px}

.single-post{padding:34px 40px}
.single-post .post-labels{margin-bottom:13px}
.single-title{font-size:32px;line-height:1.5;margin:0 0 10px;font-weight:850;letter-spacing:.01em}
.single-meta{color:var(--muted);font-size:13px;padding-bottom:18px;margin-bottom:24px;border-bottom:1px solid var(--line)}
.post-body{font-size:16px;line-height:2}
.post-body h2{font-size:25px;line-height:1.55;margin:2.1em 0 .9em;padding:12px 14px;border-left:5px solid var(--accent);background:#f4f8fc}
.post-body h3{font-size:20px;line-height:1.6;margin:1.8em 0 .7em;padding-bottom:7px;border-bottom:2px solid var(--line)}
.post-body h4{font-size:17px;margin:1.6em 0 .6em}
.post-body p{margin:0 0 1.35em}
.post-body ul,.post-body ol{margin:0 0 1.4em;padding-left:1.5em}
.post-body li{margin:.35em 0}
.post-body blockquote{margin:1.5em 0;padding:15px 18px;background:#f7f8fa;border-left:4px solid #9ca3af;color:#4b5563}
.post-body table{width:100%;border-collapse:collapse;margin:1.5em 0;display:block;overflow-x:auto;white-space:nowrap}
.post-body th,.post-body td{border:1px solid #d9dde3;padding:10px 12px;text-align:left}
.post-body th{background:#f2f4f7}
.post-body a{color:var(--accent);text-decoration:underline;text-underline-offset:2px}
.post-body img{display:block;margin:24px auto;border-radius:2px}
.post-footer{margin-top:28px;padding-top:20px;border-top:1px solid var(--line);color:var(--muted);font-size:13px}

.pager{display:flex;justify-content:space-between;gap:15px;margin:24px 0}
.pager a{display:block;background:var(--surface);border:1px solid var(--line);padding:11px 16px;font-size:13px;font-weight:700;box-shadow:var(--shadow)}

.sidebar-column .widget{background:var(--surface);border:1px solid var(--line);box-shadow:var(--shadow);margin:0 0 22px;padding:20px}
.sidebar-column .widget-title{font-size:17px;line-height:1.4;margin:-20px -20px 18px;padding:14px 18px;border-bottom:1px solid var(--line);font-weight:800}
.sidebar-column ul{list-style:none;margin:0;padding:0}
.sidebar-column li{padding:10px 0;border-bottom:1px solid #edf0f3;font-size:14px;line-height:1.55}
.sidebar-column li:last-child{border-bottom:0}
.sidebar-column .PopularPosts .item-thumbnail{float:left;margin:2px 12px 7px 0}
.sidebar-column .PopularPosts .item-thumbnail img{width:78px;height:58px;object-fit:cover}
.sidebar-column .PopularPosts .item-title{font-weight:700}
.sidebar-column .Label li{display:flex;justify-content:space-between;gap:10px}
.sidebar-column .BlogSearch form{display:flex}
.sidebar-column .BlogSearch input[type="text"]{width:100%;min-width:0;border:1px solid #d6dae0;padding:10px 11px;outline:none}
.sidebar-column .BlogSearch input[type="submit"]{border:0;background:var(--accent);color:#fff;padding:0 13px;cursor:pointer}

.recent-list{list-style:none;margin:0;padding:0}
.recent-item{display:grid;grid-template-columns:82px 1fr;gap:12px;padding:0 0 13px!important;margin:0 0 13px;border-bottom:1px solid #edf0f3!important}
.recent-item:last-child{margin-bottom:0;padding-bottom:0!important;border-bottom:0!important}
.recent-thumb{width:82px;height:62px;object-fit:cover;background:#edf0f3}
.recent-title{font-size:13px;font-weight:750;line-height:1.55;margin:0}
.recent-date{font-size:11px;color:var(--muted);margin-top:4px}

.site-footer{background:#111318;color:#c8ccd2;margin-top:40px}
.footer-inner{max-width:var(--max);margin:0 auto;padding:30px 20px 20px}
.footer-menu .widget{margin:0}
.footer-menu .widget-title{display:none}
.footer-menu ul{list-style:none;display:flex;flex-wrap:wrap;gap:6px 22px;margin:0 0 20px;padding:0}
.footer-menu a{color:#fff;font-size:13px}
.footer-bottom{border-top:1px solid rgba(255,255,255,.12);padding-top:18px;font-size:12px;color:#959ba4}

.back-to-top{position:fixed;right:18px;bottom:18px;width:42px;height:42px;border:0;border-radius:3px;background:var(--accent);color:#fff;cursor:pointer;display:none;z-index:20;box-shadow:0 4px 15px rgba(0,0,0,.2)}
.back-to-top.show{display:block}

@media (max-width:900px){
  .page-shell{grid-template-columns:1fr;gap:24px}
  .sidebar-column{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
  .sidebar-column .widget{margin:0}
}
@media (max-width:680px){
  body{font-size:15px}
  .header-inner{padding:22px 16px 18px}
  .site-title{font-size:24px}
  .site-description{font-size:13px}
  .nav-inner{padding:0 10px;overflow-x:auto;white-space:nowrap}
  .menu-slot ul{flex-wrap:nowrap}
  .page-shell{margin-top:18px;padding:0 12px}
  .post-card-grid{grid-template-columns:1fr}
  .post-card-media,.post-card-media img,.post-card-placeholder{min-height:200px;max-height:235px}
  .post-card-content{padding:19px 18px 18px}
  .post-card-title{font-size:19px}
  .single-post{padding:24px 18px}
  .single-title{font-size:25px}
  .post-body h2{font-size:21px}
  .post-body h3{font-size:18px}
  .sidebar-column{display:block}
  .sidebar-column .widget{margin-bottom:20px}
}

/* =========================================================
   Service Change Alternatives / Status Board Theme v1
   ========================================================= */
:root{--bg:#f5f2fa;--surface:#fff;--text:#251b35;--muted:#736982;--line:#e3dced;--accent:#ef5d68;--accent-dark:#cf3f4b;--nav:#241341;--radius:10px;--shadow:0 9px 26px rgba(54,31,83,.1);--cyan:#06b6c9;--purple:#7446b9;--mono:"Cascadia Code",Consolas,monospace}
body{background:linear-gradient(180deg,#eee8f7 0,#faf9fc 380px);color:var(--text)}
.site-header{background:#fff;border-bottom:1px solid var(--line)}.header-inner::before{content:"SERVICE STATUS / MIGRATION / ALTERNATIVES";display:block;margin-bottom:10px;color:var(--purple);font:700 10px/1.4 var(--mono);letter-spacing:.13em}
.site-title{letter-spacing:-.04em}.site-title a::before{content:">> ";color:var(--accent);font-family:var(--mono)}.site-description{color:var(--muted)}
.primary-nav{background:var(--nav)}.nav-home{background:var(--accent)}.menu-slot a:hover{background:rgba(6,182,201,.16)}
.post-card,.single-post,.sidebar-column .widget,.pager a{border-color:var(--line);border-radius:var(--radius);box-shadow:var(--shadow)}
.post-card{position:relative;border-left:5px solid var(--cyan)}.post-card::after{content:"STATUS UPDATE";position:absolute;right:14px;top:14px;padding:4px 8px;color:#fff;background:var(--accent);border-radius:999px;font:700 9px var(--mono);letter-spacing:.06em}
.post-labels a{background:#f2ecfb;color:#5d329c;border:1px solid #d8c5f1;border-radius:999px}.read-more{color:var(--purple)}
.post-body h2{background:#f8f4fc;border:1px solid var(--line);border-left:5px solid var(--purple)}.post-body h2::before{content:"CHANGE / ";color:var(--accent);font:700 .7em var(--mono)}
.post-body h3{border-color:#ddd2e9}.post-body blockquote{background:#eefbfc;border-left-color:var(--cyan);color:#3e5860}
.post-body table{border:1px solid var(--line)}.post-body th{background:var(--nav);color:#fff}.post-body tr:nth-child(even) td{background:#faf7fc}
.post-body code{color:#a82f3a;background:#fff0f1;border:1px solid #f5c8cc;padding:.16em .42em;border-radius:4px}
.sidebar-column .widget-title::before{content:"STATUS / ";color:var(--cyan);font:700 10px var(--mono)}.site-footer{background:var(--nav)}.back-to-top{background:var(--accent)}
@media(max-width:680px){.post-card::after{display:none}.primary-nav{position:relative}}

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

body.script:
//
(function(){
  var y=document.getElementById('copyright-year');
  if(y){y.innerHTML=String(new Date().getFullYear());}
  var topButton=document.getElementById('back-to-top');
  if(topButton){
    window.onscroll=function(){
      topButton.className=window.pageYOffset&gt;500?'back-to-top show':'back-to-top';
    };
    topButton.onclick=function(){window.scrollTo(0,0);};
  }
})();
//
